class entity_anim_tree
{
public:
  void frame_advance(float time);
};

class entity
{
public:
  entity_anim_tree *get_anim_tree(int slot) const;
};

enum { ANIM_PRIMARY = 0 };

class kellyslater_controller
{
  char pad0[0x0c];
  entity *owner;
  char pad1[0x204];
  float lastTime;
  short mAnim;
  char pad2[0x0a];
  short bAnim;
  char pad3[0xc26];
  entity *my_board_model;

public:
  entity *get_owner() { return owner; }
  void Anim(int animation, float blend_time, bool loop = true,
            float start_time = 0.0f, bool reverse = false);
  void BoardAnim(int animation, float blend_time, bool loop = true,
                 float start_time = 0.0f);
  void SetAnimAndFrame(int a, int b, float time, float blenda, float blendb,
                       bool KSLoop, bool BLoop, bool KSAnimCall, bool BAnimCall);
};

__asm__(".equ get_anim_tree__C6entityi, 0x001348D8");
__asm__(".equ frame_advance__16entity_anim_treef, 0x001177F0");
__asm__(".equ Anim__22kellyslater_controllerifbfT3, 0x00212660");
__asm__(".equ BoardAnim__22kellyslater_controllerifbf, 0x002128B0");

void kellyslater_controller::SetAnimAndFrame( int a, int b, float time, float blenda, float blendb, bool KSLoop, bool BLoop, bool KSAnimCall, bool BAnimCall )
{
  if ((bAnim != b) || BAnimCall)
  {
    BoardAnim(b, blendb, BLoop, 0);
  }
  else
  {
    if (time > lastTime)
      my_board_model->get_anim_tree(ANIM_PRIMARY)->frame_advance(time-lastTime);
    else
      my_board_model->get_anim_tree(ANIM_PRIMARY)->frame_advance(time);
  }

	if (( mAnim!=a) || KSAnimCall )
	{
		Anim(a,blenda,KSLoop,0);
	}
	else
	{
		//Anim(a,0,true,time);
		//Anim(a,0,false,time);
    if (time > lastTime)
      get_owner()->get_anim_tree(ANIM_PRIMARY)->frame_advance(time-lastTime);
    else
      get_owner()->get_anim_tree(ANIM_PRIMARY)->frame_advance(time);

		// this doesn't work - the frame doesn't update
		//mFrame=f;
    //rational_t start_time = (mFrame / 30.0f);
    //get_owner()->play_anim(ANIM_PRIMARY, g_surfer_anims[a], start_time, ANIM_NONCOSMETIC | (mAnimDir == SURFER_ANIM_REVERSE ? ANIM_REVERSE : 0));
	}
  lastTime = time;
}
